// Sessun: the new-in list is paginated (?p=1, 2, 3 ...). It had 4 pages (~70 products) when checked;
// pages past the end come back empty, so a few spare pages are fetched to cover growth.
const sessunPages = [1, 2, 3, 4, 5, 6, 7, 8].map(p => ({
  json: { shop: 'Sessun', gender: 'female', listing_url: `https://de.sessun.com/catalogue/neuheiten.html?p=${p}` },
}));

return [
  ...sessunPages,
  // Filippa K: the grid endpoint behind the "Load more items" button; sz=300 returns every new-in item in one request.
  { json: { shop: 'Filippa K', gender: 'female', listing_url: 'https://www.filippa-k.com/on/demandware.store/Sites-FilippaK-Site/en_DE/Search-UpdateGrid?cgid=woman-new-in&start=0&sz=300' } },
  { json: { shop: 'Filippa K', gender: 'male', listing_url: 'https://www.filippa-k.com/on/demandware.store/Sites-FilippaK-Site/en_DE/Search-UpdateGrid?cgid=man-new-in&start=0&sz=300' } },
];

const pages = $('Shop Listing Pages').all();
const found = new Map(); // product_url -> { shop, genders }
const base = 'https://www.filippa-k.com';
const absolute = (u) => (u.startsWith('http') ? u : base + u);
const fkLink = /href="((?:https:\/\/www\.filippa-k\.com)?\/de\/en\/[a-z0-9-]+\/[0-9]{5}-[0-9]{4}\.html)"/;

// Filippa K: the listing comes from the shop's grid endpoint (the one behind "Load more items"),
// which returns every new-in tile in one go. One tile = one product (colour); take each tile's own link.
const tileProducts = (html) => {
  const urls = [];
  for (const part of html.split(/<[^>]*class="product-tile"[^>]*>/).slice(1)) {
    const m = part.match(fkLink);
    if (m) urls.push(absolute(m[1]));
  }
  return urls;
};

const add = (url, shop, gender) => {
  if (!found.has(url)) found.set(url, { shop, genders: new Set() });
  if (gender) found.get(url).genders.add(gender);
};

$input.all().forEach((item, i) => {
  const shop = pages[i] ? pages[i].json.shop : '';
  const gender = pages[i] ? pages[i].json.gender : '';
  const html = String(item.json.data || '');
  if (shop === 'Sessun') {
    const re = /href="(https:\/\/de\.sessun\.com\/catalogue\/[a-z0-9-]+\/[a-z0-9-]+\.html)"/g;
    let m;
    while ((m = re.exec(html)) !== null) {
      const url = m[1];
      // skip size-variant duplicates like ...-m.html or ...-38.html
      if (/-(xxs|xs|s|m|l|xl|xxl|tu|[0-9]{2})\.html$/.test(url)) continue;
      if (/\/catalogue\/(taschen|schmuck|schuhe|accessoires)\//.test(url)) continue;
      add(url, shop, gender);
    }
  } else {
    const listed = tileProducts(html);
    if (listed.length) {
      new Set(listed).forEach(u => add(u, shop, gender));
    } else {
      // layout changed: keep every product link but leave gender blank rather than guess
      const re = new RegExp(fkLink.source, 'g');
      new Set([...html.matchAll(re)].map(m => absolute(m[1]))).forEach(u => add(u, shop, ''));
    }
  }
});

// a product found on both the women's and the men's list is unisex
return [...found].map(([product_url, v]) => ({
  json: { shop: v.shop, product_url, gender: v.genders.size > 1 ? 'unisex' : ([...v.genders][0] || '') }
}));

// Rows already saved in the Google Sheet (empty sheet gives one blank item)
const checked = new Set(
  $input.all()
    .map(i => String(i.json.product_url || '').trim())
    .filter(Boolean)
);
// Keep only product links that are not in the sheet yet
return $('Extract Product Links').all().filter(i => !checked.has(String(i.json.product_url || '').trim()));

const src = $('Only Unchecked Products').all();
const clean = (s) => String(s || '').replace(/<br\s*\/?>/gi, ' ').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/\s+/g, ' ').trim();

// This workflow checks clothing. Accessories (bags, shoes, jewellery, homeware ...) are skipped, hats are kept
// because they are made of the same fabrics as clothes.
const accessoryCategory = /^(sacs|chaussures|bijoux|pop-up|ceintures?|lunettes|accessoires|maroquinerie|petite-maroquinerie|foulards?|echarpes?|gants|chaussettes|parfums?|maison)/i;
const accessoryType = /(tasche|taschen|rucksack|shopper|clutch|portemonnaie|geldbeutel|pumps|ballerinas?|mokassins?|hausschuhe?|stiefel|stiefelette|sandalen?|sneakers?|schuhe?|loafers?|boots?|armband|halskette|kette|ohrringe?|ring|brosche|g(ü|u)rtel|schal|tuch|handschuhe?|socken?|brille|tasse|teller|kerzenhalter|vase|schale)$/i;
const hat = /(^|[^a-z])(hat|cap|beanie|beret|bucket|bonnet|chapeau|casquette|bob|hut|mutze|muetze|m(ü|u)tze|kappe|baskenm(ü|u)tze)([^a-z]|$)/i;
const isAccessory = (shop, html, url, name, typeWord) => {
  const segs = url.split('/').filter(Boolean);
  const slug = (shop === 'Sessun' ? segs[segs.length - 1] : segs[segs.length - 2] || '').replace(/\.html$/, '').replace(/-/g, ' ');
  if (hat.test(slug) || hat.test(name) || hat.test(typeWord)) return false;
  if (shop === 'Sessun') {
    const c = (html.match(/"category":\s*"([^"]+)"/) || [])[1] || '';
    return accessoryCategory.test(c) || accessoryType.test(typeWord);
  }
  const c = (html.match(/"category":"([A-Za-z][^"]*\/[^"]*)"/) || [])[1] || '';
  return /\/Accessories/i.test(c);
};

const out = [];
$input.all().forEach((item, i) => {
  const meta = src[i] ? src[i].json : {};
  const html = String(item.json.data || '');
  let name = '';
  let typeWord = '';
  let materials = '';
  let extra = '';
  const t = html.match(/<title>([^<]*)<\/title>/i);
  if (t) {
    const parts = clean(t[1]).split('|');
    name = parts[0].trim();
    if (meta.shop === 'Sessun' && parts.length > 2) typeWord = (parts[1] || '').trim(); // e.g. "Tasche", "Kleid"
  }
  if (isAccessory(meta.shop, html, String(meta.product_url || ''), name, typeWord)) return; // not clothing
  if (meta.shop === 'Sessun') {
    const comps = [...html.matchAll(/<p class="composition">([\s\S]*?)<\/p>/gi)].map(m => clean(m[1]));
    materials = [...new Set(comps)].join(' | ');
    const d = html.match(/itemprop="description">([\s\S]*?)<\/div>/i);
    if (d) extra = clean(d[1]);
  } else {
    const mats = [...html.matchAll(/Material:<\/span>([\s\S]*?)<\/li>/gi)].map(m => clean(m[1]));
    materials = [...new Set(mats)].join(' | ');
    const certs = [...html.matchAll(/Certificate:<\/span>([\s\S]*?)<\/li>/gi)].map(m => clean(m[1]));
    const d = html.match(/"description":"([^"]*)"/);
    extra = [d ? d[1] : '', [...new Set(certs)].join(' | ')].filter(Boolean).join(' Certificates: ');
  }
  if (!materials) return; // page did not load or has no material info; retry next run
  out.push({ json: { shop: meta.shop, gender: meta.gender || '', product_url: meta.product_url, product_name: name, materials, details: extra.slice(0, 1500) } });
});
return out;

// Builds one email for the whole run: per brand, sustainable items first, then not sustainable.
// Filippa K is split into Women / Men / Unisex sections, like the dashboard.
const DASHBOARD_URL = ''; // optional: link to your dashboard
const judged = $('Judge Materials').all();
const meta = $('Max 80 Per Run').all();
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const rows = judged.map((j, i) => {
  const m = meta[i] ? meta[i].json : {};
  const o = j.json.output || {};
  return { shop: m.shop || '', gender: m.gender || '', name: m.product_name || '', url: m.product_url || '', materials: m.materials || '', ok: o.is_sustainable === true || o.is_sustainable === 'true', fibre: o.fibre_highlight || '', note: o.assessment || '' };
}).filter(r => r.url);
if (!rows.length) return [];

const verdictBlocks = (list, showGender) => {
  const block = (title, items, colour) => {
    if (!items.length) return `<p style="color:#666;margin:4px 0 14px">${title}: none this run</p>`;
    const lines = items.sort((a, b) => a.name.localeCompare(b.name)).map(r => {
      const tag = [showGender ? r.gender : '', r.fibre].filter(Boolean).map(esc).join(' · ');
      return `<li style="margin:5px 0"><a href="${esc(r.url)}">${esc(r.name)}</a>${tag ? ` <span style="color:#666">(${tag})</span>` : ''}<br><span style="color:#555;font-size:13px">${esc(r.materials)}</span></li>`;
    }).join('');
    return `<h3 style="margin:14px 0 4px;color:${colour}">${title} (${items.length})</h3><ul style="padding-left:18px;margin:0">${lines}</ul>`;
  };
  return block('Sustainable', list.filter(r => r.ok), '#2e7d32') + block('Not sustainable', list.filter(r => !r.ok), '#b3261e');
};

const brandHtml = (shop) => {
  const mine = rows.filter(r => r.shop === shop);
  if (!mine.length) return '';
  let body = '';
  if (shop === 'Filippa K') {
    const groups = [['female', 'Women'], ['male', 'Men'], ['unisex', 'Unisex']];
    const known = groups.map(g => g[0]);
    groups.forEach(([key, title]) => {
      const l = mine.filter(r => r.gender === key);
      if (l.length) body += `<h2 style="margin:22px 0 0;font-size:18px">${title} <span style="color:#666;font-weight:normal;font-size:14px">${l.filter(r => r.ok).length} of ${l.length} pass</span></h2>` + verdictBlocks(l, false);
    });
    const rest = mine.filter(r => !known.includes(r.gender));
    if (rest.length) body += `<h2 style="margin:22px 0 0;font-size:18px">Other</h2>` + verdictBlocks(rest, false);
  } else {
    body = verdictBlocks(mine, true);
  }
  return `<h2 style="border-bottom:1px solid #ddd;padding-bottom:4px;margin-top:28px">${esc(shop)}</h2>` + body;
};

const today = new Date().toISOString().slice(0, 10);
const total = rows.length;
const yes = rows.filter(r => r.ok).length;
const html = `<div style="font-family:Arial,sans-serif;max-width:720px">` +
  `<h1 style="margin-bottom:2px">Sustainable Clothing Finder</h1>` +
  `<p style="color:#555;margin-top:0">${today}: ${total} new products checked, ${yes} sustainable.` +
  (DASHBOARD_URL ? ` <a href="${esc(DASHBOARD_URL)}">Open dashboard</a>` : '') + `</p>` +
  brandHtml('Sessun') + brandHtml('Filippa K') + `</div>`;
return [{ json: { subject: `Sustainable clothing: ${yes} of ${total} new products pass (${today})`, html, total, yes } }];
